class Zaman:
    def __enter__(self):
        print("başla")
        return self
    def __exit__(self, tur, deger, iz):
        print("bitti")

with Zaman():
    print("iş yapılıyor")

class Kapi:
    def __enter__(self):
        print("aç")
        return "oda"
    def __exit__(self, *hata):
        print("kapat")
with Kapi() as yer:
    print("içerideyim:", yer)

class Kapi:
    def __enter__(self):
        return self
    def __exit__(self, tur, deger, iz):
        print("kapı kapandı")
        return False

try:
    with Kapi():
        print(1 / 0)
except ZeroDivisionError:
    print("hata yakalandı")
